        case 0x20:
          pbDstWritePtr[0x1f] = gaPaletteColorLUT[pbLineBufSrcPixel[0x1f]][pbTileData[0x21]];
        case 0x1f:
          pbDstWritePtr[0x1e] = gaPaletteColorLUT[pbLineBufSrcPixel[0x1e]][pbTileData[0x20]];
        case 0x1e:
