        case 0xd:
          pbDstWritePtr[0xc] = gaPaletteColorLUT[pbLineBufSrcPixel[0xc]][pbTileData[0xe]];
        case 0xc:
          pbDstWritePtr[0xb] = gaPaletteColorLUT[pbLineBufSrcPixel[0xb]][pbTileData[0xd]];
