void __stdcall D2GFX_InitializeLineBuffer() {
    uint32_t nBlendValue;
    int iPixel;
    int nColorStep;
    uint8_t (*pbTileRowPtr)[32];
    int iTileRow = 0;
    int nNegColorBase = 0;
    uint8_t (*pbCurTileEntry)[32] = gpLineBufferTileArray[0];
    do {
      int nExpectedEndVal;
      nExpectedEndVal = 0;
      nColorStep = nNegColorBase;
      pbTileRowPtr = pbCurTileEntry;
      do {
        iPixel = 0;
        nBlendValue = iTileRow << 0x18;
        do {
          nBlendValue = (int)nBlendValue <= 0 ? 0 : nBlendValue;
          if ((int)nBlendValue >= 0x1f000000) {
            nBlendValue = 0x1f000000;
          }

          (*(uint8_t (*)[32])*pbTileRowPtr)[iPixel] = (uint8_t)(nBlendValue >> 0x18);
          iPixel++;
          nBlendValue += nColorStep >> 5;
        } while (iPixel < 0x20);

        if ((int)nBlendValue >> 0x18 != nExpectedEndVal) {
          Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x285);
          exit(-1);
        }

        nExpectedEndVal++;
        nColorStep += 0x1000000;
        pbTileRowPtr++;
      } while (nExpectedEndVal < 0x20);

      pbCurTileEntry += 0x20;
      iTileRow++;
      nNegColorBase += -0x1000000;
      if ((int)pbCurTileEntry >= (intptr_t)((char*)&gpLineBufferTileArray + sizeof(gpLineBufferTileArray))) {
        return;
      }
    } while (true);
}

// Initializes color lookup tables for palette blending. Populates gPaletteBlendLookupTable (256x256 entries) by blending all combinations of source and destination palette indices. Used by rendering functions for alpha blending and color effects.
void __fastcall PALETTE_InitColorLookupTables(BYTE * * ppPaletteTable) {
    // Static local variables (originally global data)
    static BYTE * gaPaletteBlendEntries[72] = {}; D2_STATIC_GUARD(gaPaletteBlendEntries, "D2gfx::D2GFX::PALETTE_InitColorLookupTables::gaPaletteBlendEntries");

    int nCount;
    uint8_t* pDstRow;
    uint8_t** pPaletteEntry = gaPaletteBlendEntries;
    for (nCount = 0x48; nCount; nCount--) {
      *pPaletteEntry = *ppPaletteTable;
      ppPaletteTable++;
      pPaletteEntry++;
    }

    gpPaletteBlendLookupTable = gaPaletteBlendEntries;
    pPaletteEntry = gaPaletteBlendEntries + 3;
    uint8_t* pDst = gaPaletteColorLUT[0];
    do {
      uint8_t* pSrcEntry;
      pSrcEntry = *pPaletteEntry;
      pPaletteEntry++;
      pDstRow = pDst;
      for (nCount = 0x40; nCount; nCount--) {
        *(uint32_t*)pDstRow = *(uint32_t*)pSrcEntry;
        pSrcEntry += 4;
        pDstRow += 4;
      }

      pDst += 0x100;
    } while ((int)pPaletteEntry < (intptr_t)((char*)&gaPaletteBlendEntries + 208));
}

